function LargestRectangle(matrix: array[,] of integer): integer;
begin
  if (matrix = nil) or (matrix.GetLength(0) = 0) then
    Result := 0;

  var rows := matrix.GetLength(0);
  var cols := matrix.GetLength(1);
  var height := ArrFill(cols + 1, 0);
  var maxArea := 0;

  for var r := 0 to rows - 1 do
  begin
    for var i := 0 to cols - 1 do
      height[i] := if matrix[r, i] = 1 then height[i] + 1 else 0;

    var stack := new Stack<integer>;
    stack.Push(-1);
    for var i := 0 to cols do
    begin
      while (stack.Count > 0) and (stack.Peek() <> -1) and (height[i] < height[stack.Peek()]) do
      begin
        var h := height[stack.Pop()];
        var w := i - 1 - stack.Peek();
        maxArea := Max(maxArea, h * w);
      end;
      stack.Push(i);
    end;
  end;

  Result := maxArea;
end;

