function MaxPerformance(n: integer; speed: array of integer; efficiency: array of integer; k: integer): integer;
begin
  var performances := ArrGen(n, i -> (efficiency[i], speed[i])).OrderByDescending(x -> x[0]).ToArray();
  var speedSum := 0;
  var heap := new SortedSet<integer>;
  var performance := 0;

  foreach var (e, s) in performances do
  begin
    if heap.Count > k - 1 then
    begin
      var minSpeed := heap.Min;
      speedSum -= minSpeed;
      heap.Remove(minSpeed);
    end;

    heap.Add(s);
    speedSum += s;
    performance := Max(performance, speedSum * e);
  end;

  Result := performance mod (1000000007);
end;

