function ShortestTour(attractions: array of integer; roads: array of (integer, integer)): array of integer;
begin
  var roadMap := new Dictionary<integer, HashSet<integer>>;
  foreach var road in roads do
  begin
    if not roadMap.ContainsKey(road[0]) then
      roadMap[road[0]] := new HashSet<integer>;
    if not roadMap.ContainsKey(road[1]) then
      roadMap[road[1]] := new HashSet<integer>;
    roadMap[road[0]].Add(road[1]);
    roadMap[road[1]].Add(road[0]);
  end;

  var shortest: array of integer;
  foreach var permutation in attractions.Permutations() do
  begin
    var valid := True;
    for var i := 0 to permutation.Length - 2 do
      if not roadMap[permutation[i]].Contains(permutation[i + 1]) then
      begin
        valid := False;
        break;
      end;

    if valid and ((shortest = nil) or (permutation.Length < shortest.Length)) then
      shortest := permutation;
  end;

  Result := shortest;
end;

function TopKFrequent(nums: array of integer; k: integer): array of integer;
begin
  var d := nums.GroupBy(x -> x).ToDictionary(g -> g.Key, g -> g.Count());
  var heap := new SortedSet<(integer, integer)>(
    Comparer&<(integer, integer)>.Create(
      (x, y) -> begin
        if x[0] = y[0] then
          Result := x[1].CompareTo(y[1])
        else
          Result := y[0].CompareTo(x[0]);
      end));

  foreach var i in d.Keys do
    heap.Add((-d[i], i));

  var res := new List<integer>;
  for var idx := 0 to k - 1 do
  begin
    res.Add(heap.Min[1]);
    heap.Remove(heap.Min);
  end;

  Result := res.ToArray();
end;

