function FindMinSteps(i: integer; j: integer; s: string; dp: array[,] of integer): integer;
begin
  if i >= j then
  begin
    Result := 0;
    exit;
  end;
  if dp[i, j] <> -1 then
  begin
    Result := dp[i, j];
    exit;
  end;
  if s[i + 1] = s[j + 1] then
    dp[i, j] := FindMinSteps(i + 1, j - 1, s, dp)
  else
    dp[i, j] := 1 + Min(FindMinSteps(i + 1, j, s, dp), FindMinSteps(i, j - 1, s, dp));
  Result := dp[i, j];
end;

