  Result := FindMinSteps(0, n - 1, s, dp);
end;

function IsContinuous(cards: array of integer): boolean;
begin
  if cards.Length <> 5 then
    Result := False;

  &Array.Sort(cards);
  var wildCards := cards.CountOf(0);

  for var i := wildCards to 4 do
  begin
    var gap := cards[i] - cards[i - 1] - 1;
    if gap > 0 then
    begin
      wildCards -= gap;
      if wildCards < 0 then
      begin
        Result := False;
        exit;
      end;
    end
    else if (cards[i] = cards[i - 1]) and (cards[i] <> 0) then
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;

function MinimumHealth(dungeon: array[,] of integer): integer;
begin
  var m := dungeon.GetLength(0);
  var n := dungeon.GetLength(1);
  var dp := new integer[m + 1, n + 1];

  for var i := 0 to m do
    for var j := 0 to n do
      dp[i, j] := integer.MaxValue;

  dp[m, n - 1] := 1;
  dp[m - 1, n] := 1;

  for var i := m - 1 downto 0 do
    for var j := n - 1 downto 0 do
    begin
      dp[i, j] := Max(1, Min(dp[i + 1, j], dp[i, j + 1]) - dungeon[i, j]);
    end;

  Result := dp[0, 0];
end;

