function GraphIsAcyclic(A: integer; B: array of integer; C: array of integer): integer;

  function DFS(adjLis: array of List<integer>; vis: array of boolean; se: HashSet<integer>; element: integer): integer;
  begin
    vis[element] := True;
    var val := 1;
    se.Add(element);
    foreach var i in adjLis[element] do
    begin
      if se.Contains(i) then
      begin
        Result := 0;
        exit;
      end;
      if not vis[i] then
      begin
        val := DFS(adjLis, vis, se, i);
        if val = 0 then
        begin
          Result := 0;
          exit;
        end;
      end;
    end;
    se.Remove(element);
    Result := 1;
  end;

begin
  var vis := ArrFill(A + 1, False);
  var lenb := B.Length;
  var se := new HashSet<integer>;
  var adjLis := new List<integer>[A + 1];

  for var i := 0 to A do
    adjLis[i] := new List<integer>;

  for var i := 0 to lenb - 1 do
    adjLis[B[i]].Add(C[i]);

  for var i := 1 to A do
  begin
    if not vis[i] then
    begin
      vis[i] := True;
      if DFS(adjLis, vis, se, i) = 0 then
      begin
        Result := 0;
        exit;
      end;
    end;
  end;

  Result := 1;
end;

function CheckCollinear(coordinates: array of (integer, integer)): boolean;

  function GetSlope(p1: (integer, integer); p2: (integer, integer)): real;
  begin
    var (x1, y1) := p1;
    var (x2, y2) := p2;
    if x2 - x1 = 0 then
      Result := real.PositiveInfinity
    else
      Result := (y2 - y1) / (x2 - x1);
  end;

begin
  if coordinates.Length < 2 then
    Result := False;

  var (x0, y0) := coordinates[0];
  var (x1, y1) := coordinates[1];
  var initialSlope := GetSlope((x0, y0), (x1, y1));

  for var i := 2 to coordinates.Length - 1 do
  begin
    var (x, y) := coordinates[i];
    if GetSlope((x0, y0), (x, y)) <> initialSlope then
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;

