function NextLexicographicPermutation(arr: array of integer): array of integer;
begin
  var pivot: integer := -1;
  for var i := arr.Length - 2 downto 0 do
  begin
    if arr[i] < arr[i + 1] then
    begin
      pivot := i;
      break;
    end;
  end;

  if pivot = -1 then
  begin
    &Array.Sort(arr);
    Result := arr;
    exit;
  end;

  var rightmostSuccessor := 0;
  for var i := arr.Length - 1 downto pivot + 1 do
  begin
    if arr[i] > arr[pivot] then
    begin
      rightmostSuccessor := i;
      break;
    end;
  end;

  Swap(arr[pivot], arr[rightmostSuccessor]);

  var left := pivot + 1;
  var right := arr.Length - 1;
  while left < right do
  begin
    Swap(arr[left], arr[right]);
    left += 1;
    right -= 1;
  end;

  Result := arr;
end;

function SumOfTwoCubes(n: integer): boolean;
begin
  var cubes := new List<integer>;
  for var i := 0 to Round(Power(n, 1/3)) + 2 do
    cubes.Add(i * i * i);

  for var i := 0 to cubes.Count - 1 do
    for var j := i to cubes.Count - 1 do
      for var k := 0 to cubes.Count - 1 do
        for var l := k to cubes.Count - 1 do
          if (cubes[i] + cubes[j] = cubes[k] + cubes[l]) and 
             ((i <> k) or (j <> l)) and 
             ((i <> l) or (j <> k)) then
          begin
            Result := True;
            exit;
          end;
  Result := False;
end;

