function FindMaxPairs(nums: array of integer; k: integer): integer;
begin
  var d := new Dictionary<integer, integer>;
  var count := 0;
  foreach var num in nums do
  begin
    var complement := k - num;
    if d.ContainsKey(complement) and (d[complement] > 0) then
    begin
      count += 1;
      d[complement] -= 1;
    end
    else
    begin
      if not d.ContainsKey(num) then
        d[num] := 0;
      d[num] += 1;
    end;
  end;
  Result := count;
end;

function NextGreatestElement(nums: array of integer): array of integer;
begin
  var stack := new Stack<integer>;
  var res := ArrFill(nums.Length, -1);

  for var i := 0 to nums.Length - 1 do
  begin
    while (stack.Count > 0) and (nums[stack.Peek()] < nums[i]) do
    begin
      res[stack.Pop()] := nums[i];
    end;
    stack.Push(i);
  end;

  Result := res;
end;

function FindDigitCount(num: integer): integer;
begin
  if num < 10 then
  begin
    Result := -1;
    exit;
  end;

  var rightmost := num mod 10;
  var count := 0;
  num := num div 10;

  while num > 0 do
  begin
    count += 1;
    var currentDigit := num mod 10;
    if currentDigit > rightmost then
    begin
      Result := count;
      exit;
    end;
    num := num div 10;
  end;

  Result := -1;
end;

function HasThreeConsecutiveEvens(arr: array of integer): boolean;
begin
  if arr.Length < 3 then
    Result := False;

  var i := 0;
  while i < arr.Length - 2 do
  begin
    if (arr[i] mod 2 = 0) and (arr[i + 1] mod 2 = 0) and (arr[i + 2] mod 2 = 0) then
    begin
      Result := True;
      exit;
    end
    else if arr[i + 1] mod 2 = 0 then
      i += 1
    else if arr[i + 2] mod 2 = 0 then
      i += 2
    else
      i += 3;
  end;

  Result := False;
end;

function ValidParenthesis(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var i in s do
  begin
    if (i = '(') or (i = ' ') or ((i >= 'a') and (i <= 'z')) then
      stack.Push(i)
    else if i = ')' then
    begin
      if (stack.Count = 0) or (stack.Peek() <> '(') then
      begin
        Result := False;
        exit;
      end;
      stack.Pop();
    end;
  end;
  Result := stack.Count = 0;
end;

