function LongestPathLength(inputStr: string): integer;
begin
  var lines := inputStr.Split(|NewLine|, System.StringSplitOptions.RemoveEmptyEntries);
  var words := new List<string>;
  var tabCount := new List<integer>;
  var res := 0;

  for var i := 0 to lines.Length - 1 do
  begin
    var word := lines[i].TrimStart(#9);
    var count := lines[i].Length - word.Length;
    while (tabCount.Count > 0) and (count <= tabCount[tabCount.Count - 1]) do
    begin
      tabCount.RemoveAt(tabCount.Count - 1);
      words.RemoveAt(words.Count - 1);
    end;

    if word.Contains('.') then
    begin
      words.Add(word);
      res := Max(res, string.Join('/', words).Length);
      words.RemoveAt(words.Count - 1);
    end
    else
    begin
      words.Add(word);
      tabCount.Add(count);
    end;
  end;

  Result := res;
end;

