function MaxSumSubarrays(nums: array of integer): array of (integer, integer);
begin
  var maxSum := integer.MinValue;
  var currentSum := 0;
  var start := 0;
  var res := new List<(integer, integer)>;

  for var endIdx := 0 to nums.Length - 1 do
  begin
    currentSum += nums[endIdx];
    if currentSum > maxSum then
    begin
      maxSum := currentSum;
      res.Clear();
      res.Add((start, endIdx));
    end
    else if currentSum = maxSum then
      res.Add((start, endIdx));

    if currentSum < 0 then
    begin
      currentSum := 0;
      start := endIdx + 1;
    end;
  end;

  Result := res.ToArray();
end;

function ReverseStringInplace(var s: string): string;
