  var right := s.Length;
  while left < right do
  begin
    var temp := s[left];
    s[left] := s[right];
    s[right] := temp;
    left += 1;
    right -= 1;
  end;
  Result := s;
end;

function KadaneAlgorithm(arr: array of integer): integer;
begin
  var maxCurrent := arr[0];
  var maxGlobal := arr[0];
  for var i := 1 to arr.Length - 1 do
  begin
    maxCurrent := Max(arr[i], maxCurrent + arr[i]);
    if maxCurrent > maxGlobal then
      maxGlobal := maxCurrent;
  end;
  Result := maxGlobal;
end;

function MergeTwoLists(l1: array of integer; l2: array of integer): array of integer;
