function ScoreOfParentheses(s: string): integer;
begin
  var stackCount := 0;
  var start := 1;
  var score := 0;
  for var endIdx := 1 to s.Length do
  begin
    if s[endIdx] = '(' then
      stackCount += 1
    else if stackCount > 0 then
      stackCount -= 1;

    if stackCount = 0 then
    begin
      if endIdx - start = 1 then
        score += 1
      else
        score += 2 * ScoreOfParentheses(s.Substring(start, endIdx - start));
      start := endIdx + 1;
    end;
  end;
  Result := score;
end;

