function NumSplits(s: string): integer;
begin
  var left := new HashSet<char>;
  var right := new Dictionary<char, integer>;
  foreach var ch in s do
  begin
    if right.ContainsKey(ch) then
      right[ch] += 1
    else
      right[ch] := 1;
  end;

  var res := 0;
  foreach var ch in s do
  begin
    left.Add(ch);
    right[ch] -= 1;
    if right[ch] = 0 then
      right.Remove(ch);

    if left.Count = right.Count then
      res += 1;
  end;
  Result := res;
end;

function RelativeSort(arr1: array of integer; arr2: array of integer): array of integer;
begin
  var countMap := new Dictionary<integer, integer>;
  foreach var num in arr1 do
  begin
    if countMap.ContainsKey(num) then
      countMap[num] += 1
    else
      countMap[num] := 1;
  end;

  var sortedArr := new List<integer>;
  var remaining := new List<integer>;

  foreach var num in arr2 do
  begin
    while countMap.ContainsKey(num) and (countMap[num] > 0) do
    begin
      sortedArr.Add(num);
      countMap[num] -= 1;
    end;
  end;

  foreach var num in arr1 do
  begin
    if (not arr2.Contains(num)) and (countMap.ContainsKey(num)) and (countMap[num] > 0) then
    begin
      remaining.Add(num);
      countMap[num] -= 1;
    end;
  end;

  remaining.Sort();
  Result := sortedArr.Concat(remaining).ToArray();
end;

