function ConvertStringToZigzag(s: string; numRows: integer): string;
begin
  if (numRows = 1) or (numRows >= s.Length) then
  begin
    Result := s;
    exit;
  end;

  var res := ArrFill(numRows, '');
  var p := 2 * (numRows - 1);

  for var i := 1 to s.Length do
  begin
    var floor := (i - 1) mod p;
    if floor >= p div 2 then
      floor := p - floor;
    res[floor] += s[i];
  end;

  Result := string.Join('', res);
end;

