      if (matrix[node, neighbor] = 1) and (not visited[neighbor]) then
        Dfs(neighbor, visited);
  end;

begin
  var n := matrix.GetLength(0);
  var visited := ArrFill(n, False);
  var components := 0;

  for var i := 0 to n - 1 do
    if not visited[i] then
    begin
      Dfs(i, visited);
      components += 1;
    end;

  Result := components;
end;

