function FindFibonacciNumbers(n: integer): integer;
begin
  var fib := new List<integer>;
  fib.Add(1);
  fib.Add(1);
  while fib[fib.Count - 1] < n do
    fib.Add(fib[fib.Count - 1] + fib[fib.Count - 2]);

  var count := 0;
  var i := fib.Count - 1;
  var tempN := n;

  while (tempN > 0) and (i >= 0) do
  begin
    while tempN >= fib[i] do
    begin
      tempN -= fib[i];
      count += 1;
    end;
    i -= 1;
  end;

  Result := count;
end;

