function FindMinHeightTrees(n: integer; edges: array of (integer, integer)): array of integer;
begin
  if n = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var res := new List<integer>;
  if n <= 2 then
  begin
    for var i := 0 to n - 1 do
      res.Add(i);
    Result := res.ToArray();
    exit;
  end;

  var adjList := new Dictionary<integer, List<integer>>;
  for var i := 0 to n - 1 do
    adjList[i] := new List<integer>;

  var degree := ArrFill(n, 0);

  foreach var (u, v) in edges do
  begin
    adjList[u].Add(v);
    adjList[v].Add(u);
    degree[u] += 1;
    degree[v] += 1;
  end;

  var nodeQueue := new Queue<integer>;
  for var i := 0 to n - 1 do
    if degree[i] = 1 then
      nodeQueue.Enqueue(i);

  var remainingNodes := n;
  while remainingNodes > 2 do
  begin
    var length := nodeQueue.Count;
    remainingNodes -= length;

    for var x := 0 to length - 1 do
    begin
      var a := nodeQueue.Dequeue();
      foreach var neighbor in adjList[a] do
      begin
        degree[neighbor] -= 1;
        if degree[neighbor] = 1 then
          nodeQueue.Enqueue(neighbor);
      end;
    end;
  end;

  while nodeQueue.Count > 0 do
    res.Add(nodeQueue.Dequeue());

  Result := res.ToArray();
end;

