  if s.Length = 0 then
  begin
    Result := '';
    exit;
  end;

  var maxLength := 1;
  var start := 1;

  for var i := 1 to s.Length do
  begin
    if (i - maxLength >= 1) and 
       (s.Substring(i - maxLength - 1, maxLength + 1) = 
        string.Create(s.Substring(i - maxLength - 1, maxLength + 1).Reverse().ToArray())) then
    begin
      start := i - maxLength - 1;
      maxLength += 2;
      continue;
    end;

    if (i - maxLength >= 0) and 
       (s.Substring(i - maxLength, maxLength + 1) = 
        string.Create(s.Substring(i - maxLength, maxLength + 1).Reverse().ToArray())) then
    begin
      start := i - maxLength;
      maxLength += 1;
    end;
  end;

  Result := s.Substring(start, maxLength);
end;

