  var stack := new Stack<char>;
  var mapping := new Dictionary<char, char>;
  mapping[')'] := '(';
  mapping['}'] := '{';
  mapping[']'] := '[';

  foreach var ch in s do
  begin
    if mapping.ContainsKey(ch) then
    begin
      var topElement := if stack.Count > 0 then stack.Pop() else '#';
      if mapping[ch] <> topElement then
