procedure F(i: integer; n1: integer; n2: integer; c1: integer; c2: integer; j: integer; balls: array of integer; var res: integer);
begin
  if (n1 > balls.Sum() div 2) or ((i - n1) > balls.Sum() div 2) then
    exit;
  if i = balls.Length then
  begin
    if (n1 = n2) and (c1 = c2) then
      res += j;
    exit;
  end;
  var x := balls[i];
  for var k := 0 to x do
    F(i + 1, n1 + k, n2 + (x - k), c1 + Ord(k <> 0), c2 + Ord(k <> x), j * Comb(x, k), balls, res);
end;

function GetProbability(balls: array of integer): real;
begin
  var n := balls.Sum();
  var total := Factorial(n) div (Factorial(n div 2) * Factorial(n div 2));
  var res := 0;
  F(0, 0, 0, 0, 0, 1, balls, res);
  Result := res / total;
end;

