  var bestMax := 0;
  var img1Ones := new List<(integer, integer)>;
  var img2Ones := new List<(integer, integer)>;
  var shiftCount := new Dictionary<(integer, integer), integer>;

  for var i := 0 to img1.GetLength(0) - 1 do
    for var j := 0 to img1.GetLength(1) - 1 do
    begin
      if img1[i, j] = 1 then
        img1Ones.Add((i, j));
      if img2[i, j] = 1 then
        img2Ones.Add((i, j));
    end;

  foreach var (r1, c1) in img1Ones do
    foreach var (r2, c2) in img2Ones do
    begin
      var rowShift := r1 - r2;
      var colShift := c1 - c2;
      var key := (rowShift, colShift);
      if shiftCount.ContainsKey(key) then
        shiftCount[key] += 1
      else
        shiftCount[key] := 1;
      bestMax := Max(bestMax, shiftCount[key]);
    end;

  Result := bestMax;
end;

