  var currentRepeat := 1;
  for var i := 2 to s.Length do
  begin
    if s[i] = s[i - 1] then
    begin
      currentRepeat += 1;
      maxRepeat := Max(maxRepeat, currentRepeat);
    end
    else
      currentRepeat := 1;
  end;
  Result := maxRepeat;
end;

function CatalanNumber(n: integer): integer;
begin
  var catalan := ArrFill(n + 1, 0);
  catalan[0] := 1;
  if n > 0 then
    catalan[1] := 1;
  for var i := 2 to n do
  begin
    catalan[i] := 0;
    for var j := 0 to i - 1 do
      catalan[i] := catalan[i] + catalan[j] * catalan[i - j - 1];
  end;
  Result := catalan[n];
end;

