  if total mod 2 <> 0 then
  begin
    Result := False;
    exit;
  end;
  var target := total div 2;
  var n := nums.Length;
  var dp := new boolean[target + 1];
  dp[0] := True;

  for var i := 0 to n - 1 do
    for var j := target downto nums[i] do
      if dp[j - nums[i]] then
        dp[j] := True;

  Result := dp[target];
end;

