function LargestInTree(root: TreeNode): integer;
begin
  if root = nil then
  begin
    Result := integer.MinValue;
    exit;
  end;
  var maxValue := root.val;
  var leftMax := LargestInTree(root.left);
  var rightMax := LargestInTree(root.right);
  if leftMax > maxValue then
    maxValue := leftMax;
  if rightMax > maxValue then
    maxValue := rightMax;
  Result := maxValue;
end;

