end;

function SmallestSubArray(nums: array of integer; target: integer): integer;
begin
  var n := nums.Length;
  var minLen := n + 1;
  var left := 0;
  var currentSum := 0;

  for var right := 0 to n - 1 do
  begin
    currentSum += nums[right];
    while currentSum >= target do
    begin
      minLen := Min(minLen, right - left + 1);
      currentSum -= nums[left];
      left += 1;
    end;
  end;

  Result := if minLen <= n then minLen else 0;
end;

function MinDifference(arr1: array of integer; arr2: array of integer): integer;
