  while (i < arr1.Length) and (j < arr2.Length) do
  begin
    minDiff := Min(minDiff, Abs(arr1[i] - arr2[j]));
    if arr1[i] < arr2[j] then
      i += 1
    else
      j += 1;
  end;
  Result := minDiff;
end;

