function MaxCollinearPoints(points: array of (real, real)): integer;

  function CalcSlope(x1: real; x2: real; y1: real; y2: real): real;
  begin
    if x1 = x2 then
      Result := real.PositiveInfinity
    else
      Result := (y2 - y1) / (x2 - x1);
  end;

begin
  var res := 1;
  for var index1 := 0 to points.Length - 1 do
  begin
    var slopes := new Dictionary<real, integer>;
    var maxPoints := 1;
    var (x1, y1) := points[index1];
    for var index2 := index1 + 1 to points.Length - 1 do
    begin
      var (x2, y2) := points[index2];
      var slope := CalcSlope(x1, x2, y1, y2);
      if slopes.ContainsKey(slope) then
        slopes[slope] += 1
      else
        slopes[slope] := 1;
      maxPoints := Max(maxPoints, 1 + slopes[slope]);
    end;
    res := Max(res, maxPoints);
  end;
  Result := res;
end;

