function AllCombinationSum(candidates: array of integer; target: integer): array of array of integer;

  procedure Dfs(i: integer; cur: List<integer>; total: integer; var res: List<array of integer>);
  begin
    if total = target then
    begin
      res.Add(cur.ToArray());
      exit;
    end;
    if (i >= candidates.Length) or (total > target) then
      exit;
    cur.Add(candidates[i]);
    Dfs(i, cur, total + candidates[i], res);
    cur.RemoveAt(cur.Count - 1);
    Dfs(i + 1, cur, total, res);
  end;

begin
  var res := new List<array of integer>;
  Dfs(0, new List<integer>, 0, res);
  Result := res.ToArray();
end;

function CheckWinner(board: array of array of char): integer;
begin
  var oCnt := 0;
  var xCnt := 0;
  var oFlag := False;
  var xFlag := False;

  foreach var line in board do
  begin
    var oLine := line.CountOf('O');
    var xLine := line.CountOf('X');
    oCnt += oLine;
    xCnt += xLine;
    if oLine = 3 then
      oFlag := True;
    if xLine = 3 then
      xFlag := True;
  end;

  for var idx := 0 to 2 do
  begin
    if (board[0][idx] = 'O') and (board[1][idx] = 'O') and (board[2][idx] = 'O') then
      oFlag := True
    else if (board[0][idx] = 'X') and (board[1][idx] = 'X') and (board[2][idx] = 'X') then
      xFlag := True;
  end;

  if ((board[0][0] = 'O') and (board[1][1] = 'O') and (board[2][2] = 'O')) or
     ((board[0][2] = 'O') and (board[1][1] = 'O') and (board[2][0] = 'O')) then
    oFlag := True
  else if ((board[0][0] = 'X') and (board[1][1] = 'X') and (board[2][2] = 'X')) or
          ((board[0][2] = 'X') and (board[1][1] = 'X') and (board[2][0] = 'X')) then
    xFlag := True;

  if oFlag and not xFlag then
    Result := 1
  else if xFlag and not oFlag then
    Result := 2
  else if oCnt + xCnt = 9 then
    Result := 0
  else
    Result := -1;
end;

function LastElementOfLongestPalindrome(s: string): char;
begin
  var n := s.Length;
  var dp := new integer[n, n];
  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 1;
    for var j := i + 1 to n - 1 do
    begin
      if s[i + 1] = s[j + 1] then
        dp[i, j] := dp[i + 1, j - 1] + 2
      else
        dp[i, j] := Max(dp[i + 1, j], dp[i, j - 1]);
    end;
  end;
  var lastElement := s[1];
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      if dp[i, j] > dp[0, 0] - 1 then
        lastElement := s[j + 1];
  Result := lastElement;
end;

function MaxLength(nums: array of integer; k: integer): integer;
