function CubeRoot(x: integer): integer;
begin
  if x < 2 then
  begin
    Result := x;
    exit;
  end;

  var left := 0;
  var right := x;
  while left < right do
  begin
    var mid := (left + right) div 2;
    if mid * mid * mid < x then
      left := mid + 1
    else
      right := mid;
  end;
  Result := if left * left * left > x then left - 1 else left;
end;

