function CanDecode(s: string): boolean;
begin
  var keypad := new Dictionary<integer, integer>;
  keypad[2] := 3;
  keypad[3] := 3;
  keypad[4] := 3;
  keypad[5] := 3;
  keypad[6] := 3;
  keypad[7] := 4;
  keypad[8] := 3;
  keypad[9] := 4;

  var n := s.Length;
  var dp := ArrFill(n + 1, False);
  dp[0] := True;

  for var i := 1 to n do
  begin
    for var j := 1 to Min(4, i) do
    begin
      if (i - j >= 0) and dp[i - j] then
      begin
        var substr := s.Substring(i - j, j);
        if substr.All(ch -> ch = substr[1]) and 
           (substr[1] in ['2'..'9']) and 
           (j <= keypad[StrToInt(substr[1])]) then
        begin
          dp[i] := True;
          break;
        end;
      end;
    end;
  end;

  Result := dp[n];
end;

function FindMinLength(gems: array of string): integer;
begin
  var gemTypes := new HashSet<string>(gems);
  var gemCount := new Dictionary<string, integer>;
  var start := 0;
  var minLength := integer.MaxValue;
  for var endIdx := 0 to gems.Length - 1 do
  begin
    if gemCount.ContainsKey(gems[endIdx]) then
      gemCount[gems[endIdx]] += 1
    else
      gemCount[gems[endIdx]] := 1;
    while gemCount.Count = gemTypes.Count do
    begin
      minLength := Min(minLength, endIdx - start + 1);
      gemCount[gems[start]] -= 1;
      if gemCount[gems[start]] = 0 then
        gemCount.Remove(gems[start]);
      start += 1;
    end;
  end;
  Result := if minLength <> integer.MaxValue then minLength else 0;
end;

