  var answer := 0;
  for var i := 1 to number.Length do
  begin
    var pos := number.Length - i;
    var num := digits.IndexOf(number[i]);
    answer += num * Round(Power(base, pos));
  end;
  Result := answer;
end;

function FindSmallestUniqueSubstring(s: string): string;
begin
  var uniqueChars := new HashSet<char>(s);
  var types := uniqueChars.Count;
  var length := s.Length;
  var l := 1;
  var r := 1;
  var ansl := 1;
  var ansr := length;
  var current := new Dictionary<char, integer>;
  current[s[1]] := 1;

  while (l < length) and (r < length) do
  begin
    if current.Count < types then
    begin
      r += 1;
      if r > length then
        break;
      if current.ContainsKey(s[r]) then
        current[s[r]] += 1
      else
        current[s[r]] := 1;
    end
    else
    begin
      if (r - l) < (ansr - ansl) then
      begin
        ansl := l;
        ansr := r;
      end;
      current[s[l]] -= 1;
      if current[s[l]] = 0 then
        current.Remove(s[l]);
      l += 1;
    end;
  end;

  Result := s.Substring(ansl, ansr - ansl + 1);
end;

