function NumUniqueWords(s: string): integer;
begin
  var words := s.ToWords;
  var uniqueWords := new HashSet<string>(words);
  var repeatWords := new HashSet<string>;

  for var i := 0 to words.Length - 1 do
  begin
    var count := 0;
    for var j := 0 to words.Length - 1 do
    begin
      if words[i] = words[j] then
        count += 1;
    end;
    if count > 1 then
      repeatWords.Add(words[i]);
  end;

  uniqueWords.ExceptWith(repeatWords);
  Result := uniqueWords.Count;
end;

function IsValidStackSequence(operations: array of string): boolean;
begin
  var stack := new Stack<integer>;
  for var i := 0 to operations.Length - 1 do
  begin
    if operations[i].StartsWith('push') then
    begin
      var elementStr := operations[i].Substring(5, operations[i].Length - 6);
      var element := StrToInt(elementStr);
      stack.Push(element);
    end
    else if operations[i].StartsWith('pop') then
    begin
      if stack.Count = 0 then
      begin
        Result := false;
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;

function CountPartitions(n, m: integer): integer;
begin
  if n = 0 then
    Result := 1
  else if (n < 0) or (m = 0) then
    Result := 0
  else
    Result := CountPartitions(n - m, m) + CountPartitions(n, m - 1);
end;

function AdjProduct(nums: array of integer): integer;
begin
  var maxProduct := nums[0] * nums[1];
  for var i := 1 to nums.Length - 2 do
  begin
    maxProduct := Max(maxProduct, nums[i] * nums[i + 1]);
  end;
  Result := maxProduct;
end;

function IsPalindromeRecursive(s: string): boolean;
begin
  if s.Length <= 1 then
    Result := true
  else if s[1] <> s[s.Length] then
    Result := false
  else
    Result := IsPalindromeRecursive(s.Substring(2, s.Length - 2));
end;

function MaxVowels(s: string; k: integer): integer;
begin
  var vowels := HSet('a', 'e', 'i', 'o', 'u');
  var currentVowels := 0;

  for var i := 1 to k do
  begin
    if vowels.Contains(s[i]) then
      currentVowels += 1;
  end;

  var maxVowels := currentVowels;

  for var i := k + 1 to s.Length do
  begin
    if vowels.Contains(s[i]) then
      currentVowels += 1;
    if vowels.Contains(s[i - k]) then
      currentVowels -= 1;
    maxVowels := Max(maxVowels, currentVowels);
  end;

  Result := maxVowels;
end;

function FindSubstring(haystack, needle: string): integer;
begin
  if needle = '' then
    Result := 0
  else
  begin
    for var i := 1 to haystack.Length - needle.Length + 1 do
    begin
      var found := true;
      for var j := 1 to needle.Length do
      begin
        if haystack[i + j - 1] <> needle[j] then
        begin
          found := false;
          break;
        end;
      end;
      if found then
      begin
        Result := i - 1;
        exit;
      end;
    end;
    Result := -1;
  end;
end;

function MaxProductOfThree(nums: array of integer): integer;
begin
  &Array.Sort(nums);
  Result := Max(nums[0] * nums[1] * nums[nums.Length - 1], 
               nums[nums.Length - 1] * nums[nums.Length - 2] * nums[nums.Length - 3]);
end;

function WaysToExpressNAsSum(n: integer): integer;
begin
  if n = 0 then
    Result := 1
  else if n < 0 then
    Result := 0
  else
    Result := WaysToExpressNAsSum(n - 1) + WaysToExpressNAsSum(n - 3) + WaysToExpressNAsSum(n - 4);
end;

function WaysToExpressNAsSumDP(n: integer): integer;
begin
  var dp := new integer[n + 1];
  dp[0] := 1;
  for var i := 1 to n do
  begin
    if i - 1 >= 0 then
      dp[i] += dp[i - 1];
    if i - 3 >= 0 then
      dp[i] += dp[i - 3];
    if i - 4 >= 0 then
      dp[i] += dp[i - 4];
  end;
  Result := dp[n];
end;

function MaxOnesSubsequence(A: array of integer; k: integer): integer;
begin
  var left := 0;
  var zeros := 0;
  var maxLength := 0;

  for var right := 0 to A.Length - 1 do
  begin
    if A[right] = 0 then
      zeros += 1;

    while zeros > k do
    begin
      if A[left] = 0 then
        zeros -= 1;
      left += 1;
    end;

    maxLength := Max(maxLength, right - left + 1);
  end;

  Result := maxLength;
end;

function MedianArrays(nums1, nums2: array of integer): real;
begin
  var combined := new List<integer>;
  combined.AddRange(nums1);
  combined.AddRange(nums2);
  combined.Sort;

  var length := combined.Count;
  if length mod 2 = 0 then
    Result := (combined[length div 2 - 1] + combined[length div 2]) / 2
  else
    Result := combined[length div 2];
end;

function DecToOct(num: integer): string;
begin
  var isNeg := num < 0;
  num := Abs(num);
  var ans := '';

  if num = 0 then
  begin
    Result := '0';
    exit;
  end;

  while num > 0 do
  begin
    var remainder := num mod 8;
    ans := remainder.ToString + ans;
    num := num div 8;
  end;

  if isNeg then
    Result := '-' + ans
  else
    Result := ans;
end;

function LargestPowerOf2(n: integer): integer;
begin
  var power := 1;
  while power * 2 <= n do
    power *= 2;
  Result := power;
end;

function DivideBy2(num: integer): integer;
begin
  var count := 0;
  while num mod 2 = 0 do
  begin
    num := num div 2;
    count += 1;
  end;
  Result := count;
end;

function MinDiffSplit(A: array of integer): integer;
begin
  var first := A[0];
  var second := 0;
  for var i := 1 to A.Length - 1 do
    second += A[i];

  var best := Abs(first - second);
  var p := 2;

  while p < A.Length do
  begin
    first += A[p - 1];
    second -= A[p - 1];
    best := Min(best, Abs(first - second));
    p += 1;
  end;

  Result := best;
end;

function CheckHarshadNumber(num: integer): boolean;
begin
  if num <= 0 then
    Result := false
  else
  begin
    var sumOfDigits := 0;
    var numStr := num.ToString;
    for var i := 1 to numStr.Length do
      sumOfDigits += StrToInt(numStr[i]);

    Result := num mod sumOfDigits = 0;
  end;
end;

function FindUniquePairs(nums: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;
  var pairs := new HashSet<(integer, integer)>;

  while left < right do
  begin
    var currentSum := nums[left] + nums[right];

    if currentSum = target then
    begin
      pairs.Add((nums[left], nums[right]));
      left += 1;
      right -= 1;
    end
    else if currentSum < target then
      left += 1
    else
      right -= 1;
  end;

  Result := pairs.Count;
end;

function MaxSubarraySum(nums: array of integer): integer;
begin
  var maxSum := integer.MinValue;
  var currSum := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    currSum := Max(nums[i], currSum + nums[i]);
    maxSum := Max(maxSum, currSum);
  end;

  Result := maxSum;
end;

function LargestPrimeFactor(numbers: array of integer): integer;
begin
  var primeNumbers := new List<integer>;
  for var i := 0 to numbers.Length - 1 do
  begin
    var num := numbers[i];
    if num > 1 then
    begin
      var isPrime := true;
      for var j := 2 to num - 1 do
      begin
        if num mod j = 0 then
        begin
          isPrime := false;
          break;
        end;
      end;
      if isPrime then
        primeNumbers.Add(num);
    end;
  end;

  if primeNumbers.Count > 0 then
    Result := primeNumbers.Max
  else
    Result := -1;
end;

function NumToSkip(rowNum, numRows: integer): (integer, integer);
begin
  var down := (numRows - rowNum - 1) * 2 - 1;
  var up := rowNum * 2 - 1;
  Result := (up + 1, down + 1);
end;

function ZigzagConversion(s: string; numRows: integer): string;
begin
  if numRows = 1 then
  begin
    Result := s;
    exit;
  end;

  var resultStr := '';

  for var firstLetterIndex := 0 to numRows - 1 do
  begin
    var (upSkip, downSkip) := NumToSkip(firstLetterIndex, numRows);
    var goingDown := true;
    var doNotAppend := false;
    var cursor := firstLetterIndex;

    while cursor < s.Length do
    begin
      if not doNotAppend then
        resultStr += s[cursor + 1];
      doNotAppend := false;

      if goingDown then
      begin
        goingDown := false;
        if downSkip <= 0 then
        begin
          doNotAppend := true;
          continue;
        end;
        cursor += downSkip;
      end
      else
      begin
        goingDown := true;
        if upSkip <= 0 then
        begin
          doNotAppend := true;
          continue;
        end;
        cursor += upSkip;
      end;
    end;
  end;

  Result := resultStr;
end;

function FindMaxMin(arr: array of integer): (integer, integer);
begin
  if arr.Length = 1 then
    Result := (arr[0], arr[0])
  else if arr.Length = 2 then
    Result := (Max(arr[0], arr[1]), Min(arr[0], arr[1]))
  else
  begin
    var mid := arr.Length div 2;
    var (leftMax, leftMin) := FindMaxMin(arr[:mid]);
    var (rightMax, rightMin) := FindMaxMin(arr[mid:]);
    Result := (Max(leftMax, rightMax), Min(leftMin, rightMin));
  end;
end;

function FindPentNum(n: integer): integer;
begin
  Result := n * (3 * n - 1) div 2;
end;

function SumNotMultipleOfThree(numbers: array of integer): integer;
begin
  var total := 0;
  for var i := 0 to numbers.Length - 1 do
  begin
    if numbers[i] mod 3 <> 0 then
      total += numbers[i];
  end;
  Result := total;
end;

function KthSmallestDivisor(n, k: integer): integer;
begin
  var factors := new List<integer>;
  for var x := 1 to Trunc(Sqrt(n)) do
  begin
    if n mod x = 0 then
    begin
      k -= 1;
      if k = 0 then
      begin
        Result := x;
        exit;
      end
      else
        factors.Add(x);
    end;
  end;

  if (factors.Count > 0) and (factors[factors.Count - 1] * factors[factors.Count - 1] = n) then
    k += 1;

  var f := factors.Count;
  if k <= f then
    Result := n div factors[f - k]
  else
    Result := -1;
end;

function LongestSubarraySumZero(arr: array of integer): integer;
begin
  var maxLen := 0;
  var sumMap := new Dictionary<integer, integer>;
  var currSum := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    currSum += arr[i];

    if (arr[i] = 0) and (maxLen = 0) then
      maxLen := 1;

    if currSum = 0 then
      maxLen := i + 1;

    if sumMap.ContainsKey(currSum) then
      maxLen := Max(maxLen, i - sumMap[currSum])
    else
      sumMap[currSum] := i;
  end;

  Result := maxLen;
end;

function SmallestPair(lst: array of integer): (integer, integer);
begin
  var sortedList := lst.ToArray;
  &Array.Sort(sortedList);
  Result := (sortedList[0], sortedList[1]);
end;

function ConvertToBase8(num: integer): string;
begin
  if num = 0 then
  begin
    Result := '0';
    exit;
  end;

  var res := '';
  var tempNum := Abs(num);

  while tempNum <> 0 do
  begin
    var r := tempNum mod 8;
    res := r.ToString + res;
    tempNum := tempNum div 8;
  end;

  if num < 0 then
    Result := '-' + res
  else
    Result := res;
end;

function NumBusesToDestination(routes: array of array of integer; source, target: integer): integer;
begin
  if source = target then
  begin
    Result := 0;
    exit;
  end;

  var stopToRoutes := new Dictionary<integer, HashSet<integer>>;
  for var i := 0 to routes.Length - 1 do
  begin
    for var j := 0 to routes[i].Length - 1 do
    begin
      var stop := routes[i][j];
      if not stopToRoutes.ContainsKey(stop) then
        stopToRoutes[stop] := new HashSet<integer>;
      stopToRoutes[stop].Add(i);
    end;
  end;

  var queue := new Queue<(integer, integer)>;
  queue.Enqueue((source, 0));
  var visitedStops := new HashSet<integer>;
  visitedStops.Add(source);
  var visitedRoutes := new HashSet<integer>;

  while queue.Count > 0 do
  begin
    var (currStop, buses) := queue.Dequeue;

    if stopToRoutes.ContainsKey(currStop) then
    begin
      foreach var route in stopToRoutes[currStop] do
      begin
        if visitedRoutes.Contains(route) then
          continue;

        visitedRoutes.Add(route);

        for var k := 0 to routes[route].Length - 1 do
        begin
          var stop := routes[route][k];
          if stop = target then
          begin
            Result := buses + 1;
            exit;
          end;

          if not visitedStops.Contains(stop) then
          begin
            visitedStops.Add(stop);
            queue.Enqueue((stop, buses + 1));
          end;
        end;
      end;
    end;
  end;

  Result := -1;
end;

function GenerateGrayCode(n: integer): array of string;
begin
  var res := new List<string>;
  for var i := 0 to (1 shl n) - 1 do
  begin
    var gray := i xor (i shr 1);
    var binaryStr := '';

    for var bit := n - 1 downto 0 do
    begin
      if (gray and (1 shl bit)) <> 0 then
        binaryStr += '1'
      else
        binaryStr += '0';
    end;

    res.Add(binaryStr);
  end;

  Result := res.ToArray;
end;

procedure GenerateCombinations(start: integer; current: List<integer>; length: integer; myList: array of integer; res: List<array of integer>);
begin
  if current.Count = length then
  begin
    res.Add(current.ToArray);
    exit;
  end;

  for var i := start to myList.Length - 1 do
  begin
    current.Add(myList[i]);
    GenerateCombinations(i + 1, current, length, myList, res);
    current.RemoveAt(current.Count - 1);
  end;
end;

function CombinationsList(myList: array of integer; length: integer): array of array of integer;
begin
  var res := new List<array of integer>;
  GenerateCombinations(0, new List<integer>, length, myList, res);
  Result := res.ToArray;
end;

function FindRepeatedElements(lst: array of integer): array of integer;
begin
  var elementCount := new Dictionary<integer, integer>;
  var repeatedElements := new List<integer>;

  for var i := 0 to lst.Length - 1 do
  begin
    var element := lst[i];
    if elementCount.ContainsKey(element) then
      elementCount[element] += 1
    else
      elementCount[element] := 1;
  end;

  foreach var pair in elementCount do
  begin
    if pair.Value > 1 then
      repeatedElements.Add(pair.Key);
  end;

  Result := repeatedElements.ToArray;
end;

function FindLongestIncreasingSubsequence(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var dp := new integer[nums.Length];
  for var i := 0 to nums.Length - 1 do
    dp[i] := 1;

  for var i := 1 to nums.Length - 1 do
  begin
    var maxLength := 0;
    for var j := 0 to i - 1 do
    begin
      if nums[i] > nums[j] then
        maxLength := Max(maxLength, dp[j]);
    end;
    dp[i] := maxLength + 1;
  end;

  Result := dp.Max;
end;

function IsPal(str: string): boolean;
begin
  var left := 1;
  var right := str.Length;
  while left < right do
  begin
    if str[left] <> str[right] then
    begin
      Result := false;
      exit;
    end;
    left += 1;
    right -= 1;
  end;
  Result := true;
end;

procedure Dfs(remaining: string; path: List<string>; res: List<array of string>);
begin
  if remaining = '' then
  begin
    res.Add(path.ToArray);
    exit;
  end;

  for var i := 1 to remaining.Length do
  begin
    var substr := remaining.Substring(1, i);
    if IsPal(substr) then
    begin
      var newPath := new List<string>(path);
      newPath.Add(substr);
      Dfs(remaining.Substring(i + 1), newPath, res);
    end;
  end;
end;

function PalindromePartitions(s: string): array of array of string;
begin
  var res := new List<array of string>;
  Dfs(s, new List<string>, res);
  Result := res.ToArray;
end;

function IsValidHtmlTag(tag: string): boolean;
begin
  if (tag.Length < 3) or (tag[1] <> '<') or (tag[tag.Length] <> '>') then
  begin
    Result := false;
    exit;
  end;

  var tagName := tag.Substring(2, tag.Length - 2);

  if tagName.Length = 0 then
  begin
    Result := false;
    exit;
  end;

  if not (tagName[1] in ['a'..'z']) then
  begin
    Result := false;
    exit;
  end;

  for var i := 2 to tagName.Length do
  begin
    var ch := tagName[i];
    if not (ch in ['a'..'z']) and not (ch in ['0'..'9']) and (ch <> '-') and (ch <> '_') then
    begin
      Result := false;
      exit;
    end;
  end;

  Result := true;
end;

function FindMajority(arr: array of integer): integer;
begin
  var count := 0;
  var candidate := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    if count = 0 then
      candidate := arr[i];

    if arr[i] = candidate then
      count += 1
    else
      count -= 1;
  end;

  Result := candidate;
end;

function MinRemovalsForPalindrome(arr: array of integer): integer;
begin
  var left := 0;
  var right := arr.Length - 1;
  var removals := 0;

  while left < right do
  begin
    if arr[left] <> arr[right] then
      removals += 1;
    left += 1;
    right -= 1;
  end;

  Result := removals;
end;

function FindMaxVowelWord(words: array of string): string;
begin
  var vowels := HSet('a', 'e', 'i', 'o', 'u');
  var maxVowels := 0;
  var maxWord := '';

  for var i := 0 to words.Length - 1 do
  begin
    var count := 0;
    for var j := 1 to words[i].Length do
    begin
      if vowels.Contains(words[i][j]) then
        count += 1;
    end;

    if count > maxVowels then
    begin
      maxVowels := count;
      maxWord := words[i];
    end;
  end;

  Result := maxWord;
end;

function MostOccurringCharacter(str: string): char;
begin
  var count := new Dictionary<char, integer>;

  for var i := 1 to str.Length do
  begin
    var ch := str[i];
    if count.ContainsKey(ch) then
      count[ch] += 1
    else
      count[ch] := 1;
  end;

  var maxChar := ' ';
  var maxCount := 0;

  foreach var pair in count do
  begin
    if pair.Value > maxCount then
    begin
      maxCount := pair.Value;
      maxChar := pair.Key;
    end;
  end;

  Result := maxChar;
end;

function RemoveElements(var nums: array of integer; val: integer): integer;
begin
  var i := 0;
  var j := 0;

  while j < nums.Length do
  begin
    if nums[j] <> val then
    begin
      nums[i] := nums[j];
      i += 1;
    end;
    j += 1;
  end;

  Result := i;
end;

function GCD(a, b: integer): integer;
begin
  while b <> 0 do
  begin
    var temp := b;
    b := a mod b;
    a := temp;
  end;
  Result := a;
end;

function CountEqualCharSubstrings(s: string): integer;
begin
  var total := 0;
  var count := 1;

  for var i := 2 to s.Length do
  begin
    if s[i] = s[i - 1] then
      count += 1
    else
    begin
      total += (count * (count + 1)) div 2;
      count := 1;
    end;
  end;

  total += (count * (count + 1)) div 2;
  Result := total;
end;

function MaxNonNegative(numbers: array of integer): integer;
begin
  var maxNum := -1;

  for var i := 0 to numbers.Length - 1 do
  begin
    if (numbers[i] >= 0) and (numbers[i] > maxNum) then
      maxNum := numbers[i];
  end;

  if maxNum = -1 then
    Result := 0
  else
    Result := maxNum;
end;

function GetMid(a, b: (real, real); r: real): ((real, real), (real, real));
begin
  var (ax, ay) := a;
  var (bx, by) := b;
  var lx := bx - ax;
  var ly := by - ay;
  var lxy := Sqrt(lx * lx + ly * ly);
  var r2 := r * r;

  if (lxy / 2) * (lxy / 2) > r2 then
    Result := ((0.0, 0.0), (0.0, 0.0))
  else
  begin
    var l := Sqrt(r2 - (lxy / 2) * (lxy / 2));
    var yy := l * lx / lxy;
    var xx := l * ly / lxy;
    var mx := (ax + bx) / 2;
    var my := (ay + by) / 2;
    Result := ((mx + xx, my - yy), (mx - xx, my + yy));
  end;
end;

function IsIn(rx, ry, x, y, r: real): boolean;
begin
  var r2 := r * r;
  Result := (rx - x) * (rx - x) + (ry - y) * (ry - y) <= r2 + 0.01;
end;

function CountIn(rx, ry: real; points: array of (real, real); r: real): integer;
begin
  var cnt := 0;
  for var i := 0 to points.Length - 1 do
  begin
    var (x, y) := points[i];
    if IsIn(rx, ry, x, y, r) then
      cnt += 1;
  end;
  Result := cnt;
end;

function MaxPointsCovered(points: array of (real, real); r: real): integer;
begin
  var maxRes := 1;
  var mapT := new HashSet<(real, real)>;

  for var ii := 0 to points.Length - 1 do
  begin
    for var jj := ii + 1 to points.Length - 1 do
    begin
      var (c1, c2) := GetMid(points[ii], points[jj], r);
      var (rx1, ry1) := c1;
      var (rx2, ry2) := c2;

      if rx1 = 0.0 then
        continue;

      var cnt1 := 0;
      if not mapT.Contains((rx1, ry1)) then
        cnt1 := CountIn(rx1, ry1, points, r);

      var cnt2 := 0;
      if not mapT.Contains((rx2, ry2)) then
        cnt2 := CountIn(rx2, ry2, points, r);

      mapT.Add((rx1, ry1));
      mapT.Add((rx2, ry2));
      maxRes := Max(maxRes, Max(cnt1, cnt2));
    end;
  end;

  Result := maxRes;
end;

function GetSumOfDivisors(n: integer): integer;
begin
  var res := 0;
  var i := 1;

  while i <= n div 2 do
  begin
    if n mod i = 0 then
      res += i;
    i += 1;
  end;

  Result := res;
end;

function LongestSubarraySum(arr: array of integer; k: integer): integer;
begin
  var maxLen := 0;
  var currentSum := 0;
  var left := 0;

  for var right := 0 to arr.Length - 1 do
  begin
    currentSum += arr[right];

    while (currentSum > k) and (left <= right) do
    begin
      currentSum -= arr[left];
      left += 1;
    end;

    maxLen := Max(maxLen, right - left + 1);
  end;

  Result := maxLen;
end;

type
  TreeNode = class
    val: integer;
    left, right: TreeNode;

    constructor Create(v: integer; l, r: TreeNode);
    begin
      val := v;
      left := l;
      right := r;
    end;
  end;

function CountLeafNodes(root: TreeNode): integer;
begin
  if root = nil then
  begin
    Result := 0;
    exit;
  end;

  var queue := new Queue<TreeNode>;
  queue.Enqueue(root);
  var leafCount := 0;

  while queue.Count > 0 do
  begin
    var node := queue.Dequeue;
    if (node.left = nil) and (node.right = nil) then
      leafCount += 1;

    if node.left <> nil then
      queue.Enqueue(node.left);

    if node.right <> nil then
      queue.Enqueue(node.right);
  end;

  Result := leafCount;
end;

function SumFibonacci(n: integer): integer;
begin
  if n <= 0 then
  begin
    Result := 0;
    exit;
  end;

  var fib := new List<integer>;
  fib.Add(0);
  fib.Add(1);

  for var i := 2 to n - 1 do
    fib.Add(fib[fib.Count - 1] + fib[fib.Count - 2]);

  Result := fib.Sum;
end;

function UniqueBinarySearchTrees(n: integer): integer;
begin
  var catalan := new integer[n + 1];
  for var i := 0 to n do
    catalan[i] := 0;

  catalan[0] := 1;
  catalan[1] := 1;

  for var i := 2 to n do
  begin
    for var j := 0 to i - 1 do
    begin
      catalan[i] += catalan[j] * catalan[i - j - 1];
    end;
  end;

  Result := catalan[n];
end;

