function NumWaysToReachLastCell(m, n: integer): integer;
begin
  if (m = 1) or (n = 1) then
  begin
    Result := 1;
    exit;
  end;

  var dp := new integer[m, n];

  for var i := 0 to m - 1 do
    dp[i, 0] := 1;

  for var j := 0 to n - 1 do
    dp[0, j] := 1;

  for var i := 1 to m - 1 do
  begin
    for var j := 1 to n - 1 do
    begin
      dp[i, j] := dp[i - 1, j] + dp[i, j - 1];
    end;
  end;

  Result := dp[m - 1, n - 1];
end;

