  begin
    Result := '';
    exit;
  end;

  var res := new StringBuilder;
  var prevChar := inputString[1];
  res.Append(prevChar);

  for var i := 2 to inputString.Length do
  begin
    var currentChar := inputString[i];
    if currentChar <> prevChar then
    begin
      res.Append(currentChar);
      prevChar := currentChar;
    end;
  end;

  Result := res.ToString;
end;

function MinimumSwaps(arr: array of integer): integer;
begin
  var n := arr.Length;
  var ans := 0;
  var temp := arr.ToArray;
  &Array.Sort(temp);
  var visited := new boolean[n];

  for var i := 0 to n - 1 do
  begin
    if visited[i] or (temp[i] = arr[i]) then
      continue;

    var cycleSize := 0;
    var j := i;

    while not visited[j] do
    begin
      visited[j] := true;
      var index := &Array.IndexOf(temp, arr[j]);
      j := index;
      cycleSize += 1;
    end;

    if cycleSize > 0 then
      ans += cycleSize - 1;
  end;

  Result := ans;
end;

