  end;

  var uniqueNums := new List<integer>;
  foreach var pair in frequency do
  begin
    if pair.Value = 1 then
      uniqueNums.Add(pair.Key);
  end;

  if uniqueNums.Count > 0 then
    Result := uniqueNums.Min
  else
    Result := -1;
end;

