function BinaryInsertionSort(arr: array of integer): array of integer;
begin
  var res := arr.ToArray;

  for var i := 1 to res.Length - 1 do
  begin
    var val := res[i];
    var left := 0;
    var right := i - 1;

    while left <= right do
    begin
      var mid := (left + right) div 2;
      if res[mid] > val then
        right := mid - 1
      else
        left := mid + 1;
    end;

    for var j := i - 1 downto left do
      res[j + 1] := res[j];

    res[left] := val;
  end;

  Result := res;
end;

function QuickSort(arr: array of integer): array of integer;
begin
  if arr.Length <= 1 then
  begin
    Result := arr;
    exit;
  end;

  var pivot := arr[arr.Length div 2];
  var left := new List<integer>;
  var middle := new List<integer>;
  var right := new List<integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    if arr[i] < pivot then
      left.Add(arr[i])
    else if arr[i] = pivot then
      middle.Add(arr[i])
    else
      right.Add(arr[i]);
  end;

  Result := QuickSort(left.ToArray) + middle.ToArray + QuickSort(right.ToArray);
end;

function FindKthLargest(nums: array of integer; k: integer): integer;
begin
  if (nums.Length = 0) or (k <= 0) then
  begin
    Result := -1;
    exit;
  end;

  var heap := new List<integer>;

  for var i := 0 to nums.Length - 1 do
  begin
    heap.Add(nums[i]);

    if heap.Count > k then
    begin
      heap.Sort;
      heap.RemoveAt(0);
    end;
  end;

  heap.Sort;
  Result := heap[0];
end;

