  &Array.Sort(sortedArr);

  var minDiff := integer.MaxValue;
  for var i := 1 to sortedArr.Length - 1 do
  begin
    var diff := sortedArr[i] - sortedArr[i - 1];
    if diff < minDiff then
      minDiff := diff;
  end;

  Result := minDiff;
end;

function SumEvenProductOdd(nums: array of integer): (integer, integer);
begin
  var sumEven := 0;
  var productOdd := 1;
  var hasOdd := false;

  for var i := 0 to nums.Length - 1 do
  begin
    if nums[i] mod 2 = 0 then
      sumEven += nums[i]
    else
    begin
      productOdd *= nums[i];
      hasOdd := true;
    end;
  end;

  if not hasOdd then
    productOdd := 1;

  Result := (sumEven, productOdd);
end;

