function ConvertToISO(date: string): string;
begin
  var months := new Dictionary<string, string>;
  months['January'] := '01';
  months['February'] := '02';
  months['March'] := '03';
  months['April'] := '04';
  months['May'] := '05';
  months['June'] := '06';
  months['July'] := '07';
  months['August'] := '08';
  months['September'] := '09';
  months['October'] := '10';
  months['November'] := '11';
  months['December'] := '12';

  var parts := date.ToWords;
  if parts.Length <> 3 then
  begin
    Result := '';
    exit;
  end;

  var dayStr := parts[0];
  if dayStr.Length > 2 then
    dayStr := dayStr.Substring(1, dayStr.Length - 2);

  if dayStr.Length = 1 then
    dayStr := '0' + dayStr;

  var month := months[parts[1]];
  var year := parts[2];

  Result := year + '-' + month + '-' + dayStr;
end;

