type
  TreeNode = class
    val: integer;
    left, right: TreeNode;

    constructor Create(v: integer; l, r: TreeNode);
    begin
      val := v;
      left := l;
      right := r;
    end;
  end;

function FindLevel(root: TreeNode; k: integer): integer;
begin
  if root = nil then
  begin
    Result := 0;
    exit;
  end;

  if root.val = k then
  begin
    Result := 1;
    exit;
  end;

  var leftLevel := FindLevel(root.left, k);
  if leftLevel > 0 then
  begin
    Result := leftLevel + 1;
    exit;
  end;

  var rightLevel := FindLevel(root.right, k);
  if rightLevel > 0 then
  begin
    Result := rightLevel + 1;
    exit;
  end;

  Result := 0;
end;

function SquareOdd(nums: array of integer): array of integer;
begin
