  for var i := 0 to nums.Length - 1 do
  begin
    if nums[i] mod 2 <> 0 then
      res[i] := nums[i] * nums[i]
    else
      res[i] := 0;
  end;

  Result := res;
end;

function GCDLCM(a, b: integer): (integer, integer);
begin
  var c := Max(a, b);
  var d := Min(a, b);
  var t := 1;

  while t > 0 do
  begin
    t := c mod d;
    c := d;
    d := t;
  end;

  var gcd := c;
  var lcm := (a * b) div gcd;

  Result := (gcd, lcm);
end;

function ReorderString(s: string; indices: array of integer): string;
