  Result := new string(resultArr);
end;

function SimplifyPath(path: string): string;
begin
  var parts := path.Split('/');
  var stack := new Stack<string>;

  for var i := 0 to parts.Length - 1 do
  begin
    if (parts[i] = '') or (parts[i] = '.') then
      continue
    else if parts[i] = '..' then
    begin
      if stack.Count > 0 then
        stack.Pop;
    end
    else
      stack.Push(parts[i]);
  end;

  var resultParts := stack.ToArray;
  &Array.Reverse(resultParts);

  Result := '/' + string.Join('/', resultParts);
end;

