function FindInMatrix(matrix: array of array of integer; target: integer): boolean;
begin
  if (matrix.Length = 0) or (matrix[0].Length = 0) then
  begin
    Result := false;
    exit;
  end;

  var m := matrix.Length;
  var n := matrix[0].Length;

  var row := 0;
  var col := n - 1;

  while (row < m) and (col >= 0) do
  begin
    if matrix[row, col] = target then
    begin
      Result := true;
      exit;
    end
    else if matrix[row, col] < target then
      row += 1
    else
      col -= 1;
  end;

  Result := false;
end;

