function BitwiseSubtract(x, y: integer): integer;
begin
  while y <> 0 do
  begin
    var borrow := (not x) and y;
    x := x xor y;
    y := borrow shl 1;
  end;
  Result := x;
end;

function IntervalsIntersection(list1, list2: array of (integer, integer)): array of (integer, integer);
begin
  var res := new List<(integer, integer)>;
  var i := 0;
  var j := 0;

  while (i < list1.Length) and (j < list2.Length) do
  begin
    var start := Max(list1[i].Item1, list2[j].Item1);
    var endVal := Min(list1[i].Item2, list2[j].Item2);

    if start <= endVal then
      res.Add((start, endVal));

    if list1[i].Item2 < list2[j].Item2 then
      i += 1
    else
      j += 1;
  end;

  Result := res.ToArray;
end;

function IsPerfectPower(n: integer): boolean;
begin
  if n < 2 then
  begin
    Result := false;
    exit;
  end;

  for var base := 2 to Trunc(Sqrt(n)) do
  begin
    var exponent := 2;
    while Power(base, exponent) <= n do
    begin
      if Power(base, exponent) = n then
      begin
        Result := true;
        exit;
      end;
      exponent += 1;
    end;
  end;

  Result := false;
end;

function LongestLCIS(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var maxLen := 1;
  var currentLen := 1;

  for var i := 1 to nums.Length - 1 do
  begin
    if nums[i] > nums[i - 1] then
    begin
      currentLen += 1;
      maxLen := Max(maxLen, currentLen);
    end
    else
      currentLen := 1;
  end;

  Result := maxLen;
end;

function IsPowerOf2(n: integer): boolean;
begin
  if n <= 0 then
  begin
    Result := false;
    exit;
  end;

  while n <> 1 do
  begin
    if n mod 2 <> 0 then
    begin
      Result := false;
      exit;
    end;
    n := n div 2;
  end;

  Result := true;
end;

function MatrixAddition(A, B: array[,] of integer): array[,] of integer;
begin
  var n1 := A.GetLength(0);
  var n2 := A.GetLength(1);
  var newA := new integer[n1, n2];

  for var i := 0 to n1 - 1 do
  begin
    for var j := 0 to n2 - 1 do
    begin
      newA[i, j] := A[i, j] + B[i, j];
    end;
  end;

  Result := newA;
end;

function Modes(numbers: array of integer): array of integer;
begin
  var count := new Dictionary<integer, integer>;

  for var i := 0 to numbers.Length - 1 do
  begin
    if count.ContainsKey(numbers[i]) then
      count[numbers[i]] += 1
    else
      count[numbers[i]] := 1;
  end;

  var maxCount := count.Values.Max;
  var res := new List<integer>;

  foreach var pair in count do
  begin
    if pair.Value = maxCount then
      res.Add(pair.Key);
  end;

  res.Sort;
  Result := res.ToArray;
end;

procedure DFS(city: integer; visit: HashSet<integer>; isConnected: array of array of integer);
begin
  visit.Add(city);
  for var another := 0 to isConnected.Length - 1 do
  begin
    if (another <> city) and (isConnected[city, another] = 1) and (not visit.Contains(another)) then
      DFS(another, visit, isConnected);
  end;
end;

function FindCircleNum(isConnected: array of array of integer): integer;
begin
  var visit := new HashSet<integer>;
  var province := 0;
  var n := isConnected.Length;

  for var city := 0 to n - 1 do
  begin
    if not visit.Contains(city) then
    begin
      province += 1;
      DFS(city, visit, isConnected);
    end;
  end;

  Result := province;
end;
